import React from 'react';
import { Link } from 'react-router-dom';
import '../styles/GlobalStyles.css';

const Home = () => (
  <div className="container">
    <div className="card">
      <h1>Welcome to EventPlatform</h1>
      <p>Discover and join upcoming virtual events.</p>
      <Link to="/attendee/dashboard">
        <button className="btn">Explore Events</button>
      </Link>
    </div>
  </div>
);

export default Home;
